KG42.register("nodes-8f90e057efd249f103be5ba7",{"id":"COMP-0e667e8e9feb7467","code":"PRC025","label":"Optimized microgrid pricing with fixed trading quantities and household-cost protection","definition":"Module 2 fixes the transaction quantity ME_{k,h}, obtains the microgrid unit electricity price MP_h in a model with min C_{total} as the objective, and satisfies 0≤MP_h≤GP_h and C_k≤C_k^{NoTrade} for each household; the resulting price remains fixed during the solution of Module 3.","layer":"L6","template_code":"JOC","concept_id":"pricing.local","concept_ids":["pricing.local"],"identity_dimensions":{"identity_fields":["Object: microgrid electricity unit price MP_h","Core operation: optimize price determination under fixed transaction quantity, price bounds, and household cost protection conditions","Output: time-of-use microgrid price used by the quantity allocation model"]},"exclusions":["The price unit is cent/kWh, with the grid price GP_h as the upper bound","In the first round, the transaction quantity is initialized with DS_{k,h} from Module 1, and subsequently ME_{k,h} from Module 3 is used","In each round, the price is determined first, and then the transaction quantity","C_{total} does not directly include MP_h; MP_h enters the constraints through the transaction payment in household costs","The no-transaction cost benchmark is provided by Module 1"],"members":[{"id":"29-smart_home_trading::v141-c-R001::V::pricing.local","rule_id":"v141-c-R001","market_meaning":"The local allocation calculation uses the microgrid energy prices provided by Module 2 as inputs. Scope: ECO-Trade Module 3 household energy allocation within one microgrid. Condition: Microgrid prices supplied by Module 2 are held constant during the Module 3 solve. The Module 2 microgrid price calculation precedes the Module 3 microgrid energy allocation calculation within each iteration. Scope: Within each iteration of the ECO-Trade Module 2–Module 3 loop. For a household, total energy consumption must equal total available energy under Constraint (25). Scope: Household energy balance in ECO-Trade Module 3 local allocation. Total energy sold to the microgrid by households must equal total energy bought from the microgrid by households. Scope: Aggregate household allocations in the ECO-Trade Module 3 microgrid model. Constraint (28) limits the maximum amount of energy the household may sell to the microgrid. Scope: Household sale allocations in ECO-Trade Module 3. Condition: The household is a seller at the timeslot. Constraint (28) defines the household's minimum energy requirement from the microgrid. Scope: Household purchase allocations in ECO-Trade Module 3. Condition: The household is a buyer. The allocation must keep a participating household's cost at or below its cost without microgrid trading. Scope: Household cost protection in ECO-Trade local microgrid allocation. Condition: The household participates in microgrid trading.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Aggregate household allocations in the ECO-Trade Module 3 microgrid model. | ECO-Trade Module 3 household energy allocation within one microgrid. | Household cost protection in ECO-Trade local microgrid allocation. | Household energy balance in ECO-Trade Module 3 local allocation. | Household purchase allocations in ECO-Trade Module 3. | Household sale allocations in ECO-Trade Module 3. | Within each iteration of the ECO-Trade Module 2–Module 3 loop.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E10","v141-b-g02-E23","v141-b-g02-E24","v141-b-g02-E25","v141-b-g02-E27","v141-b-g02-E29"]},"constraint_refs":["29-smart_home_trading::v141-c-R001::v141-c-R001-C001","29-smart_home_trading::v141-c-R001::v141-c-R001-C002"],"decision_anchor":"clearing.local","source_rule_sha256":"04319d5e27fde853c07fd3b1322c30898f893d824566eafb61480ac1889a2cd9","paper":"29-smart_home_trading","rule_ref":"29-smart_home_trading::v141-c-R001","node_id":"pricing.local","function":"pricing.local","unit_id":"29-smart_home_trading::v141-a-M01::pricing.local","mechanism_id":"v141-a-M01","anchor":false},{"id":"29-smart_home_trading::v141-c-R006::V::pricing.local","rule_id":"v141-c-R006","market_meaning":"Module 3 provides its computed household microgrid-energy allocations ME_{k,h} to Module 2 as fixed inputs for determining the microgrid price. Scope: ECO-Trade's iterative allocation and price updates within one microgrid. Condition: When the loop continues to a Module 2 solve after Module 3; the first Module 2 solve instead uses Module 1's DS_{k,h} values. The microgrid price MP_{h} must be nonnegative and must not exceed the grid price GP_{h}. Scope: ECO-Trade Module 2 price determination, for every timeslot h in H. Module 2 determines the microgrid price using minimization of C_{total}, the total cost of all households, as its sole objective. Scope: ECO-Trade Module 2 price determination. Condition: Microgrid-energy quantities ME_{k,h} are held fixed during the Module 2 solve. The price-determination model must keep each household's total cost when trading no greater than its cost without microgrid trading. Scope: ECO-Trade Module 2 price optimization, for each participating household.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"pricing","context_text":"ECO-Trade Module 2 price determination, for every timeslot h in H. | ECO-Trade Module 2 price determination. | ECO-Trade Module 2 price optimization, for each participating household. | ECO-Trade's iterative allocation and price updates within one microgrid.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E10","v141-b-g01-E11","v141-b-g01-E25","v141-b-g02-E16","v141-b-g02-E20","v141-b-g02-E22","v141-b-g02-E23"]},"constraint_refs":["29-smart_home_trading::v141-c-R006::v141-c-R006-C001","29-smart_home_trading::v141-c-R006::v141-c-R006-C002","29-smart_home_trading::v141-c-R006::v141-c-R006-C003","29-smart_home_trading::v141-c-R006::v141-c-R006-C004"],"decision_anchor":"pricing.local","source_rule_sha256":"8b9f4cc4eae0bdbd9a0fbece1a0bdeb4123c1752a2f5025ea0855b2bcb7f4a42","paper":"29-smart_home_trading","rule_ref":"29-smart_home_trading::v141-c-R006","node_id":"pricing.local","function":"pricing.local","unit_id":"29-smart_home_trading::v141-a-M01::pricing.local","mechanism_id":"v141-a-M01","anchor":true}],"paper_ids":["29-smart_home_trading"],"evidence":[{"evidence_id":"v141-b-g02-E24","location":{"location_id":"src-7328a27ed1-p06-c1r3__v141-a-M01-clearing","page":6,"printed_page":null,"section":"3.3 Module 3: Energy computation module","anchor_text":"fehousehold cost when it participates in microgrid trading must be less ththan or equal to the cost ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"The third module computes the microgrid energy, ME_{k,h}, using the constant microgrid prices, MP_{h}, provided by Module 2. The optimization model of Module 3 is similar to Module 2. The main differences are: (1) it does not require Constraints (22) and (23) because microgrid prices are constants, and (2) Constraint (21) of Module 2 is modified as Constraint (25). Module 3 also requires the following constraints.","paper":"29-smart_home_trading","rule_id":"v141-c-R001","quote":"The third module computes the microgrid energy, ME_{k,h}, using the constant microgrid prices, MP_{h}, provided by Module 2. The optimization model of Module 3 is similar to Module 2. The main differences are: (1) it does not require Constraints (22) and (23) because microgrid prices are constants, and (2) Constraint (21) of Module 2 is modified as Constraint (25). Module 3 also requires the following constraints."},{"evidence_id":"v141-b-g01-E27","location":{"location_id":"src-7328a27ed1-p02-c2r2__v141-a-M01-clearing","page":2,"printed_page":null,"section":"Nomenclature","anchor_text":"MQk , h demand or supply of microgrid energy (MQk , h , a po- sitive value represents the minimum en","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"DS_{k,h} energy demand or supply of a household (DS_{k,h} \\in \\mathbb{R}, a positive value represents energy demand and a negative value represents energy surplus). DS_{k,h} is a variable in Module 1 and a parameter in Module 2 ME_{k,h} energy traded in microgrid (ME_{k,h} \\in \\mathbb{R}, a positive value represents a buyer and a negative value represents a seller). ME_{k,h} is a parameter in Module 2 and a variable in Module 3 MP_h price of microgrid energy (MP_h \\in \\mathbb{R}^+). MP_h is a variable in Module 2 and a parameter in Module 3","paper":"29-smart_home_trading","rule_id":"v141-c-R001","quote":"DS_{k,h} energy demand or supply of a household (DS_{k,h} \\in \\mathbb{R}, a positive value represents energy demand and a negative value represents energy surplus). DS_{k,h} is a variable in Module 1 and a parameter in Module 2 ME_{k,h} energy traded in microgrid (ME_{k,h} \\in \\mathbb{R}, a positive value represents a buyer and a negative value represents a seller). ME_{k,h} is a parameter in Module 2 and a variable in Module 3 MP_h price of microgrid energy (MP_h \\in \\mathbb{R}^+). MP_h is a variable in Module 2 and a parameter in Module 3"},{"evidence_id":"v141-b-g01-E09","location":{"location_id":"src-7328a27ed1-p04-c1r3__v141-a-M01-coordination","page":4,"printed_page":null,"section":"3. The ECO-Trade algorithm","anchor_text":"final solution. Algorithm 1 describes the pseudocode of the proposed su algorithm. Module 1 calculat","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Algorithm 1 describes the pseudocode of the proposed algorithm. Module 1 calculates the energy demand and generation of individual households. Module 2 determines the microgrid energy price. Module 3 computes the amount of microgrid energy being traded at a given price. The ECO-Trade algorithm iteratively generates the microgrid price (Module 2) and microgrid energy (Module 3) until a termination criterion is satisfied. Module 3 provides the final solution. We introduce the following variables to control the flow of the algorithm: previous cost C_pre, current cost C_cur, threshold value ε, threshold counter ε_count, maximum threshold counter limit ε_max, and cost improvement ε_cur. x represents the final solution.","paper":"29-smart_home_trading","rule_id":"v141-c-R001","quote":"Algorithm 1 describes the pseudocode of the proposed algorithm. Module 1 calculates the energy demand and generation of individual households. Module 2 determines the microgrid energy price. Module 3 computes the amount of microgrid energy being traded at a given price. The ECO-Trade algorithm iteratively generates the microgrid price (Module 2) and microgrid energy (Module 3) until a termination criterion is satisfied. Module 3 provides the final solution. We introduce the following variables to control the flow of the algorithm: previous cost C_pre, current cost C_cur, threshold value ε, threshold counter ε_count, maximum threshold counter limit ε_max, and cost improvement ε_cur. x represents the final solution."},{"evidence_id":"v141-b-g01-E10","location":{"location_id":"src-7328a27ed1-p04-c1r4__v141-a-M01-coordination","page":4,"printed_page":null,"section":"Algorithm 1","anchor_text":"w 5: end for 6: MEk , h DSk , h th 7: while count max do th 8: solve Module 2 Provides MPh to Module","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Algorithm 1. ECO-Trade Algorithm Input: input parameters (described in the Nomenclature section) Output: a Pareto optimal solution: x 1: ε_count ← 0, ε_max ← 3, ε ← 0.001, C_pre ← 0 2: for k = 1 to K do 3: solve Module 1 4: C_pre ← C_pre + C_k^{NoTrade} 5: end for 6: ME_{k,h} ← DS_{k,h} 7: while ε_count ≤ ε_max do 8: solve Module 2  ▷ Provides MP_h to Module 3 9: solve Module 3  ▷ Provides ME_{k,h} to Module 2 10: C_cur ← C_total 11: ε_cur = |(C_pre - C_cur)/C_pre| 12: if ε_cur ≤ ε then 13: ε_count ← ε_count + 1 14: else 15: ε_count ← 0 16: end if 17: C_pre ← C_cur 18: end while 19: x ← Module 3 Solution 20: return x","paper":"29-smart_home_trading","rule_id":"v141-c-R001","quote":"Algorithm 1. ECO-Trade Algorithm Input: input parameters (described in the Nomenclature section) Output: a Pareto optimal solution: x 1: ε_count ← 0, ε_max ← 3, ε ← 0.001, C_pre ← 0 2: for k = 1 to K do 3: solve Module 1 4: C_pre ← C_pre + C_k^{NoTrade} 5: end for 6: ME_{k,h} ← DS_{k,h} 7: while ε_count ≤ ε_max do 8: solve Module 2  ▷ Provides MP_h to Module 3 9: solve Module 3  ▷ Provides ME_{k,h} to Module 2 10: C_cur ← C_total 11: ε_cur = |(C_pre - C_cur)/C_pre| 12: if ε_cur ≤ ε then 13: ε_count ← ε_count + 1 14: else 15: ε_count ← 0 16: end if 17: C_pre ← C_cur 18: end while 19: x ← Module 3 Solution 20: return x"},{"evidence_id":"v141-b-g01-E09","location":{"location_id":"src-7328a27ed1-p04-c1r3__v141-a-M01-coordination","page":4,"printed_page":null,"section":"3. The ECO-Trade algorithm","anchor_text":"final solution. Algorithm 1 describes the pseudocode of the proposed su algorithm. Module 1 calculat","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Algorithm 1 describes the pseudocode of the proposed algorithm. Module 1 calculates the energy demand and generation of individual households. Module 2 determines the microgrid energy price. Module 3 computes the amount of microgrid energy being traded at a given price. The ECO-Trade algorithm iteratively generates the microgrid price (Module 2) and microgrid energy (Module 3) until a termination criterion is satisfied. Module 3 provides the final solution. We introduce the following variables to control the flow of the algorithm: previous cost C_pre, current cost C_cur, threshold value ε, threshold counter ε_count, maximum threshold counter limit ε_max, and cost improvement ε_cur. x represents the final solution.","paper":"29-smart_home_trading","rule_id":"v141-c-R006","quote":"Algorithm 1 describes the pseudocode of the proposed algorithm. Module 1 calculates the energy demand and generation of individual households. Module 2 determines the microgrid energy price. Module 3 computes the amount of microgrid energy being traded at a given price. The ECO-Trade algorithm iteratively generates the microgrid price (Module 2) and microgrid energy (Module 3) until a termination criterion is satisfied. Module 3 provides the final solution. We introduce the following variables to control the flow of the algorithm: previous cost C_pre, current cost C_cur, threshold value ε, threshold counter ε_count, maximum threshold counter limit ε_max, and cost improvement ε_cur. x represents the final solution."},{"evidence_id":"v141-b-g01-E10","location":{"location_id":"src-7328a27ed1-p04-c1r4__v141-a-M01-coordination","page":4,"printed_page":null,"section":"Algorithm 1","anchor_text":"w 5: end for 6: MEk , h DSk , h th 7: while count max do th 8: solve Module 2 Provides MPh to Module","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Algorithm 1. ECO-Trade Algorithm Input: input parameters (described in the Nomenclature section) Output: a Pareto optimal solution: x 1: ε_count ← 0, ε_max ← 3, ε ← 0.001, C_pre ← 0 2: for k = 1 to K do 3: solve Module 1 4: C_pre ← C_pre + C_k^{NoTrade} 5: end for 6: ME_{k,h} ← DS_{k,h} 7: while ε_count ≤ ε_max do 8: solve Module 2  ▷ Provides MP_h to Module 3 9: solve Module 3  ▷ Provides ME_{k,h} to Module 2 10: C_cur ← C_total 11: ε_cur = |(C_pre - C_cur)/C_pre| 12: if ε_cur ≤ ε then 13: ε_count ← ε_count + 1 14: else 15: ε_count ← 0 16: end if 17: C_pre ← C_cur 18: end while 19: x ← Module 3 Solution 20: return x","paper":"29-smart_home_trading","rule_id":"v141-c-R006","quote":"Algorithm 1. ECO-Trade Algorithm Input: input parameters (described in the Nomenclature section) Output: a Pareto optimal solution: x 1: ε_count ← 0, ε_max ← 3, ε ← 0.001, C_pre ← 0 2: for k = 1 to K do 3: solve Module 1 4: C_pre ← C_pre + C_k^{NoTrade} 5: end for 6: ME_{k,h} ← DS_{k,h} 7: while ε_count ≤ ε_max do 8: solve Module 2  ▷ Provides MP_h to Module 3 9: solve Module 3  ▷ Provides ME_{k,h} to Module 2 10: C_cur ← C_total 11: ε_cur = |(C_pre - C_cur)/C_pre| 12: if ε_cur ≤ ε then 13: ε_count ← ε_count + 1 14: else 15: ε_count ← 0 16: end if 17: C_pre ← C_cur 18: end while 19: x ← Module 3 Solution 20: return x"},{"evidence_id":"v141-b-g01-E11","location":{"location_id":"src-7328a27ed1-p04-c2r1__v141-a-M01-clearing","page":4,"printed_page":null,"section":"3.1 Module 1: Initial demand and supply module","anchor_text":"Applied Energy 238 (2019) 1434–1443 y, 3.1. Module 1: Initial demand and supply module al al- Module","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Module 1 optimizes the energy cost for the individual households when they do not participate in microgrid energy trading. It computes the initial values of energy supply and demand, DS_{k,h} (defined later in (16)). Module 2 uses the values of DS_{k,h} as constants in the first iteration of the ECO-Trade algorithm.","paper":"29-smart_home_trading","rule_id":"v141-c-R006","quote":"Module 1 optimizes the energy cost for the individual households when they do not participate in microgrid energy trading. It computes the initial values of energy supply and demand, DS_{k,h} (defined later in (16)). Module 2 uses the values of DS_{k,h} as constants in the first iteration of the ECO-Trade algorithm."},{"evidence_id":"v141-b-g02-E16","location":{"location_id":"src-7328a27ed1-p05-c2r2__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.1.12 Demand and supply constraints","anchor_text":"y g p Constraint (15) limits the power that can be drawn from the grid. 6) GEk , h Lkmax , ( k K , h","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"Module 2 computes the microgrid energy price. In this module, microgrid energy ME_{k,h} is a constant and microgrid energy price MP_{h} is a variable.","paper":"29-smart_home_trading","rule_id":"v141-c-R006","quote":"Module 2 computes the microgrid energy price. In this module, microgrid energy ME_{k,h} is a constant and microgrid energy price MP_{h} is a variable."},{"evidence_id":"v141-b-g02-E22","location":{"location_id":"src-7328a27ed1-p06-c1r2__v141-a-M01-pricing","page":6,"printed_page":null,"section":"3.2.3 Microgrid energy price constraints","anchor_text":"4 Fig. 2. Relationship between the ECO-Trade algorithm and the Optimal Models with/without Pareto Op","equation_id":"Eqs. (21)-(24)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"Constraints (22) and (23) define the maximum and minimum limits of microgrid energy price. MP_{h} \\ge 0, \\quad (h \\in H) \\quad (22); MP_{h} \\le GP_{h}, \\quad (h \\in H) \\quad (23)","paper":"29-smart_home_trading","rule_id":"v141-c-R006","quote":"Constraints (22) and (23) define the maximum and minimum limits of microgrid energy price. MP_{h} \\ge 0, \\quad (h \\in H) \\quad (22); MP_{h} \\le GP_{h}, \\quad (h \\in H) \\quad (23)"},{"evidence_id":"v141-b-g01-E25","location":{"location_id":"src-7328a27ed1-p05-c2r3__v141-a-M01-pricing","page":5,"printed_page":null,"section":"3.2.1 Objective function","anchor_text":"microgrid energy MEk , h is a constant and microgrid energy price MPh is es a variable. 3.2.1. Objec","equation_id":"(17)-(19)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The proposed model in Module 2 is a multi-objective optimization problem which is expressed as (17). \\min (C_{total}, C_1, C_2, \\ldots, C_k) (17) Here, C_{total} is the total cost of all households and C_k is the total cost of the k-th household which are expressed in (18) and (19) respectively. C_{total} = \\sum_{k \\in K} \\sum_{h \\in H} GP_h \\cdot GE_{k,h} + \\sum_{k \\in K} \\sum_{i \\in I} d_{k,i} \\left( \\tau_{k,i} - \\left( \\sum_{h \\in H} r_{k,i,h} \\cdot h + t_{k,i} - 1 \\right) \\right) (18) C_k = \\sum_{h \\in H} GP_h \\cdot GE_{k,h} + \\sum_{h \\in H} MP_h \\cdot ME_{k,h} + \\sum_{i \\in I} d_{k,i} \\left( \\tau_{k,i} - \\left( \\sum_{h \\in H} r_{k,i,h} \\cdot h + t_{k,i} - 1 \\right) \\right) (19)","paper":"29-smart_home_trading","rule_id":"v141-c-R006","quote":"The proposed model in Module 2 is a multi-objective optimization problem which is expressed as (17). \\min (C_{total}, C_1, C_2, \\ldots, C_k) (17) Here, C_{total} is the total cost of all households and C_k is the total cost of the k-th household which are expressed in (18) and (19) respectively. C_{total} = \\sum_{k \\in K} \\sum_{h \\in H} GP_h \\cdot GE_{k,h} + \\sum_{k \\in K} \\sum_{i \\in I} d_{k,i} \\left( \\tau_{k,i} - \\left( \\sum_{h \\in H} r_{k,i,h} \\cdot h + t_{k,i} - 1 \\right) \\right) (18) C_k = \\sum_{h \\in H} GP_h \\cdot GE_{k,h} + \\sum_{h \\in H} MP_h \\cdot ME_{k,h} + \\sum_{i \\in I} d_{k,i} \\left( \\tau_{k,i} - \\left( \\sum_{h \\in H} r_{k,i,h} \\cdot h + t_{k,i} - 1 \\right) \\right) (19)"},{"evidence_id":"v141-b-g02-E20","location":{"location_id":"src-7328a27ed1-p05-c2r4__v141-a-M01-pricing","page":5,"printed_page":null,"section":"3.2.1 Objective function","anchor_text":"me The total energy bought from the microgrid is the same as the total energy sold to the microgrid.","equation_id":"Eq. (20)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The total energy bought from the microgrid is the same as the total energy sold to the microgrid. Therefore, microgrid energy price does not have an impact on the total cost. Hence, Eq. (18) does not require the microgrid energy cost. This multi-objective optimization problem is solved by using C_{total} as the sole objective function and the remaining objective functions, C_{k}, are added as inequality constraints (Constraint (24) discussed later). Therefore, the objective function of Module 2 is defined as (20). \\min C_{total} \\quad (20)","paper":"29-smart_home_trading","rule_id":"v141-c-R006","quote":"The total energy bought from the microgrid is the same as the total energy sold to the microgrid. Therefore, microgrid energy price does not have an impact on the total cost. Hence, Eq. (18) does not require the microgrid energy cost. This multi-objective optimization problem is solved by using C_{total} as the sole objective function and the remaining objective functions, C_{k}, are added as inequality constraints (Constraint (24) discussed later). Therefore, the objective function of Module 2 is defined as (20). \\min C_{total} \\quad (20)"},{"evidence_id":"v141-b-g02-E23","location":{"location_id":"src-7328a27ed1-p06-c1r3__v141-a-M01-participation","page":6,"printed_page":null,"section":"3.3 Module 3: Energy computation module","anchor_text":"fehousehold cost when it participates in microgrid trading must be less ththan or equal to the cost ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"condition"},"source_text":"Constraint (24) implements Pareto optimality. It ensues that a household cost when it participates in microgrid trading must be less than or equal to the cost when it does not participate. C_{k} \\le C_{k}^{NoTrade}, \\quad (k \\in K) \\quad (24)","paper":"29-smart_home_trading","rule_id":"v141-c-R006","quote":"Constraint (24) implements Pareto optimality. It ensues that a household cost when it participates in microgrid trading must be less than or equal to the cost when it does not participate. C_{k} \\le C_{k}^{NoTrade}, \\quad (k \\in K) \\quad (24)"}],"candidate_only":true,"classification_subtypes":["constrained_optimization_price_formation"],"projection_statuses":["clear"],"taxonomy":{"primary_family":"kind-L6-fbb82f65ff","secondary_families":[],"stage":"L6","ontological_kind":"constrained_optimization_price_formation"},"semantic_definition":{},"source_units":[{"unit_id":"29-smart_home_trading::v141-a-M01::pricing.local","paper_id":"29-smart_home_trading","mechanism_id":"v141-a-M01","function":"pricing.local","source_occurrences":[{"id":"29-smart_home_trading::v141-c-R001::V::pricing.local","rule_id":"v141-c-R001","market_meaning":"The local allocation calculation uses the microgrid energy prices provided by Module 2 as inputs. Scope: ECO-Trade Module 3 household energy allocation within one microgrid. Condition: Microgrid prices supplied by Module 2 are held constant during the Module 3 solve. The Module 2 microgrid price calculation precedes the Module 3 microgrid energy allocation calculation within each iteration. Scope: Within each iteration of the ECO-Trade Module 2–Module 3 loop. For a household, total energy consumption must equal total available energy under Constraint (25). Scope: Household energy balance in ECO-Trade Module 3 local allocation. Total energy sold to the microgrid by households must equal total energy bought from the microgrid by households. Scope: Aggregate household allocations in the ECO-Trade Module 3 microgrid model. Constraint (28) limits the maximum amount of energy the household may sell to the microgrid. Scope: Household sale allocations in ECO-Trade Module 3. Condition: The household is a seller at the timeslot. Constraint (28) defines the household's minimum energy requirement from the microgrid. Scope: Household purchase allocations in ECO-Trade Module 3. Condition: The household is a buyer. The allocation must keep a participating household's cost at or below its cost without microgrid trading. Scope: Household cost protection in ECO-Trade local microgrid allocation. Condition: The household participates in microgrid trading.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Aggregate household allocations in the ECO-Trade Module 3 microgrid model. | ECO-Trade Module 3 household energy allocation within one microgrid. | Household cost protection in ECO-Trade local microgrid allocation. | Household energy balance in ECO-Trade Module 3 local allocation. | Household purchase allocations in ECO-Trade Module 3. | Household sale allocations in ECO-Trade Module 3. | Within each iteration of the ECO-Trade Module 2–Module 3 loop.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E10","v141-b-g02-E23","v141-b-g02-E24","v141-b-g02-E25","v141-b-g02-E27","v141-b-g02-E29"]},"constraint_refs":["29-smart_home_trading::v141-c-R001::v141-c-R001-C001","29-smart_home_trading::v141-c-R001::v141-c-R001-C002"],"decision_anchor":"clearing.local","source_rule_sha256":"04319d5e27fde853c07fd3b1322c30898f893d824566eafb61480ac1889a2cd9"},{"id":"29-smart_home_trading::v141-c-R006::V::pricing.local","rule_id":"v141-c-R006","market_meaning":"Module 3 provides its computed household microgrid-energy allocations ME_{k,h} to Module 2 as fixed inputs for determining the microgrid price. Scope: ECO-Trade's iterative allocation and price updates within one microgrid. Condition: When the loop continues to a Module 2 solve after Module 3; the first Module 2 solve instead uses Module 1's DS_{k,h} values. The microgrid price MP_{h} must be nonnegative and must not exceed the grid price GP_{h}. Scope: ECO-Trade Module 2 price determination, for every timeslot h in H. Module 2 determines the microgrid price using minimization of C_{total}, the total cost of all households, as its sole objective. Scope: ECO-Trade Module 2 price determination. Condition: Microgrid-energy quantities ME_{k,h} are held fixed during the Module 2 solve. The price-determination model must keep each household's total cost when trading no greater than its cost without microgrid trading. Scope: ECO-Trade Module 2 price optimization, for each participating household.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"pricing","context_text":"ECO-Trade Module 2 price determination, for every timeslot h in H. | ECO-Trade Module 2 price determination. | ECO-Trade Module 2 price optimization, for each participating household. | ECO-Trade's iterative allocation and price updates within one microgrid.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E10","v141-b-g01-E11","v141-b-g01-E25","v141-b-g02-E16","v141-b-g02-E20","v141-b-g02-E22","v141-b-g02-E23"]},"constraint_refs":["29-smart_home_trading::v141-c-R006::v141-c-R006-C001","29-smart_home_trading::v141-c-R006::v141-c-R006-C002","29-smart_home_trading::v141-c-R006::v141-c-R006-C003","29-smart_home_trading::v141-c-R006::v141-c-R006-C004"],"decision_anchor":"pricing.local","source_rule_sha256":"8b9f4cc4eae0bdbd9a0fbece1a0bdeb4123c1752a2f5025ea0855b2bcb7f4a42"}],"constraints":[{"constraint_id":"v141-c-R001-C001","kind":"procedural","role":"core","statement":"The local allocation calculation uses the microgrid energy prices provided by Module 2 as inputs. Scope: ECO-Trade Module 3 household energy allocation within one microgrid. Condition: Microgrid prices supplied by Module 2 are held constant during the Module 3 solve.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local","clearing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E24","v141-b-g01-E27"],"ref":"29-smart_home_trading::v141-c-R001::v141-c-R001-C001","source_rule_id":"v141-c-R001","evidence":[{"evidence_id":"v141-b-g02-E24","location":{"location_id":"src-7328a27ed1-p06-c1r3__v141-a-M01-clearing","page":6,"printed_page":null,"section":"3.3 Module 3: Energy computation module","anchor_text":"fehousehold cost when it participates in microgrid trading must be less ththan or equal to the cost ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"The third module computes the microgrid energy, ME_{k,h}, using the constant microgrid prices, MP_{h}, provided by Module 2. The optimization model of Module 3 is similar to Module 2. The main differences are: (1) it does not require Constraints (22) and (23) because microgrid prices are constants, and (2) Constraint (21) of Module 2 is modified as Constraint (25). Module 3 also requires the following constraints."},{"evidence_id":"v141-b-g01-E27","location":{"location_id":"src-7328a27ed1-p02-c2r2__v141-a-M01-clearing","page":2,"printed_page":null,"section":"Nomenclature","anchor_text":"MQk , h demand or supply of microgrid energy (MQk , h , a po- sitive value represents the minimum en","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"DS_{k,h} energy demand or supply of a household (DS_{k,h} \\in \\mathbb{R}, a positive value represents energy demand and a negative value represents energy surplus). DS_{k,h} is a variable in Module 1 and a parameter in Module 2 ME_{k,h} energy traded in microgrid (ME_{k,h} \\in \\mathbb{R}, a positive value represents a buyer and a negative value represents a seller). ME_{k,h} is a parameter in Module 2 and a variable in Module 3 MP_h price of microgrid energy (MP_h \\in \\mathbb{R}^+). MP_h is a variable in Module 2 and a parameter in Module 3"}]},{"constraint_id":"v141-c-R001-C002","kind":"procedural","role":"core","statement":"The Module 2 microgrid price calculation precedes the Module 3 microgrid energy allocation calculation within each iteration. Scope: Within each iteration of the ECO-Trade Module 2–Module 3 loop.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local","clearing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E10"],"ref":"29-smart_home_trading::v141-c-R001::v141-c-R001-C002","source_rule_id":"v141-c-R001","evidence":[{"evidence_id":"v141-b-g01-E09","location":{"location_id":"src-7328a27ed1-p04-c1r3__v141-a-M01-coordination","page":4,"printed_page":null,"section":"3. The ECO-Trade algorithm","anchor_text":"final solution. Algorithm 1 describes the pseudocode of the proposed su algorithm. Module 1 calculat","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Algorithm 1 describes the pseudocode of the proposed algorithm. Module 1 calculates the energy demand and generation of individual households. Module 2 determines the microgrid energy price. Module 3 computes the amount of microgrid energy being traded at a given price. The ECO-Trade algorithm iteratively generates the microgrid price (Module 2) and microgrid energy (Module 3) until a termination criterion is satisfied. Module 3 provides the final solution. We introduce the following variables to control the flow of the algorithm: previous cost C_pre, current cost C_cur, threshold value ε, threshold counter ε_count, maximum threshold counter limit ε_max, and cost improvement ε_cur. x represents the final solution."},{"evidence_id":"v141-b-g01-E10","location":{"location_id":"src-7328a27ed1-p04-c1r4__v141-a-M01-coordination","page":4,"printed_page":null,"section":"Algorithm 1","anchor_text":"w 5: end for 6: MEk , h DSk , h th 7: while count max do th 8: solve Module 2 Provides MPh to Module","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Algorithm 1. ECO-Trade Algorithm Input: input parameters (described in the Nomenclature section) Output: a Pareto optimal solution: x 1: ε_count ← 0, ε_max ← 3, ε ← 0.001, C_pre ← 0 2: for k = 1 to K do 3: solve Module 1 4: C_pre ← C_pre + C_k^{NoTrade} 5: end for 6: ME_{k,h} ← DS_{k,h} 7: while ε_count ≤ ε_max do 8: solve Module 2  ▷ Provides MP_h to Module 3 9: solve Module 3  ▷ Provides ME_{k,h} to Module 2 10: C_cur ← C_total 11: ε_cur = |(C_pre - C_cur)/C_pre| 12: if ε_cur ≤ ε then 13: ε_count ← ε_count + 1 14: else 15: ε_count ← 0 16: end if 17: C_pre ← C_cur 18: end while 19: x ← Module 3 Solution 20: return x"}]},{"constraint_id":"v141-c-R006-C001","kind":"procedural","role":"core","statement":"Module 3 provides its computed household microgrid-energy allocations ME_{k,h} to Module 2 as fixed inputs for determining the microgrid price. Scope: ECO-Trade's iterative allocation and price updates within one microgrid. Condition: When the loop continues to a Module 2 solve after Module 3; the first Module 2 solve instead uses Module 1's DS_{k,h} values.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.local","pricing.local"],"variable_refs":[],"parameter_refs":["v141-c-R006-th02","v141-c-R006-th04"],"evidence_ids":["v141-b-g01-E09","v141-b-g01-E10","v141-b-g01-E11","v141-b-g02-E16"],"ref":"29-smart_home_trading::v141-c-R006::v141-c-R006-C001","source_rule_id":"v141-c-R006","evidence":[{"evidence_id":"v141-b-g01-E09","location":{"location_id":"src-7328a27ed1-p04-c1r3__v141-a-M01-coordination","page":4,"printed_page":null,"section":"3. The ECO-Trade algorithm","anchor_text":"final solution. Algorithm 1 describes the pseudocode of the proposed su algorithm. Module 1 calculat","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Algorithm 1 describes the pseudocode of the proposed algorithm. Module 1 calculates the energy demand and generation of individual households. Module 2 determines the microgrid energy price. Module 3 computes the amount of microgrid energy being traded at a given price. The ECO-Trade algorithm iteratively generates the microgrid price (Module 2) and microgrid energy (Module 3) until a termination criterion is satisfied. Module 3 provides the final solution. We introduce the following variables to control the flow of the algorithm: previous cost C_pre, current cost C_cur, threshold value ε, threshold counter ε_count, maximum threshold counter limit ε_max, and cost improvement ε_cur. x represents the final solution."},{"evidence_id":"v141-b-g01-E10","location":{"location_id":"src-7328a27ed1-p04-c1r4__v141-a-M01-coordination","page":4,"printed_page":null,"section":"Algorithm 1","anchor_text":"w 5: end for 6: MEk , h DSk , h th 7: while count max do th 8: solve Module 2 Provides MPh to Module","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Algorithm 1. ECO-Trade Algorithm Input: input parameters (described in the Nomenclature section) Output: a Pareto optimal solution: x 1: ε_count ← 0, ε_max ← 3, ε ← 0.001, C_pre ← 0 2: for k = 1 to K do 3: solve Module 1 4: C_pre ← C_pre + C_k^{NoTrade} 5: end for 6: ME_{k,h} ← DS_{k,h} 7: while ε_count ≤ ε_max do 8: solve Module 2  ▷ Provides MP_h to Module 3 9: solve Module 3  ▷ Provides ME_{k,h} to Module 2 10: C_cur ← C_total 11: ε_cur = |(C_pre - C_cur)/C_pre| 12: if ε_cur ≤ ε then 13: ε_count ← ε_count + 1 14: else 15: ε_count ← 0 16: end if 17: C_pre ← C_cur 18: end while 19: x ← Module 3 Solution 20: return x"},{"evidence_id":"v141-b-g01-E11","location":{"location_id":"src-7328a27ed1-p04-c2r1__v141-a-M01-clearing","page":4,"printed_page":null,"section":"3.1 Module 1: Initial demand and supply module","anchor_text":"Applied Energy 238 (2019) 1434–1443 y, 3.1. Module 1: Initial demand and supply module al al- Module","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Module 1 optimizes the energy cost for the individual households when they do not participate in microgrid energy trading. It computes the initial values of energy supply and demand, DS_{k,h} (defined later in (16)). Module 2 uses the values of DS_{k,h} as constants in the first iteration of the ECO-Trade algorithm."},{"evidence_id":"v141-b-g02-E16","location":{"location_id":"src-7328a27ed1-p05-c2r2__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.1.12 Demand and supply constraints","anchor_text":"y g p Constraint (15) limits the power that can be drawn from the grid. 6) GEk , h Lkmax , ( k K , h","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"Module 2 computes the microgrid energy price. In this module, microgrid energy ME_{k,h} is a constant and microgrid energy price MP_{h} is a variable."}]},{"constraint_id":"v141-c-R006-C002","kind":"mathematical","role":"core","statement":"The microgrid price MP_{h} must be nonnegative and must not exceed the grid price GP_{h}. Scope: ECO-Trade Module 2 price determination, for every timeslot h in H.","expression":"MP_{h} \\ge 0, \\quad MP_{h} \\le GP_{h}, \\quad (h \\in H) \\quad (22)-(23)","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":["v141-c-R006-x01"],"parameter_refs":["v141-c-R006-th01"],"evidence_ids":["v141-b-g02-E22"],"ref":"29-smart_home_trading::v141-c-R006::v141-c-R006-C002","source_rule_id":"v141-c-R006","evidence":[{"evidence_id":"v141-b-g02-E22","location":{"location_id":"src-7328a27ed1-p06-c1r2__v141-a-M01-pricing","page":6,"printed_page":null,"section":"3.2.3 Microgrid energy price constraints","anchor_text":"4 Fig. 2. Relationship between the ECO-Trade algorithm and the Optimal Models with/without Pareto Op","equation_id":"Eqs. (21)-(24)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"Constraints (22) and (23) define the maximum and minimum limits of microgrid energy price. MP_{h} \\ge 0, \\quad (h \\in H) \\quad (22); MP_{h} \\le GP_{h}, \\quad (h \\in H) \\quad (23)"}]},{"constraint_id":"v141-c-R006-C003","kind":"mathematical","role":"core","statement":"Module 2 determines the microgrid price using minimization of C_{total}, the total cost of all households, as its sole objective. Scope: ECO-Trade Module 2 price determination. Condition: Microgrid-energy quantities ME_{k,h} are held fixed during the Module 2 solve.","expression":"\\min C_{total} \\quad (20)","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":["v141-c-R006-x01"],"parameter_refs":["v141-c-R006-th01","v141-c-R006-th02"],"evidence_ids":["v141-b-g01-E25","v141-b-g02-E16","v141-b-g02-E20"],"ref":"29-smart_home_trading::v141-c-R006::v141-c-R006-C003","source_rule_id":"v141-c-R006","evidence":[{"evidence_id":"v141-b-g01-E25","location":{"location_id":"src-7328a27ed1-p05-c2r3__v141-a-M01-pricing","page":5,"printed_page":null,"section":"3.2.1 Objective function","anchor_text":"microgrid energy MEk , h is a constant and microgrid energy price MPh is es a variable. 3.2.1. Objec","equation_id":"(17)-(19)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The proposed model in Module 2 is a multi-objective optimization problem which is expressed as (17). \\min (C_{total}, C_1, C_2, \\ldots, C_k) (17) Here, C_{total} is the total cost of all households and C_k is the total cost of the k-th household which are expressed in (18) and (19) respectively. C_{total} = \\sum_{k \\in K} \\sum_{h \\in H} GP_h \\cdot GE_{k,h} + \\sum_{k \\in K} \\sum_{i \\in I} d_{k,i} \\left( \\tau_{k,i} - \\left( \\sum_{h \\in H} r_{k,i,h} \\cdot h + t_{k,i} - 1 \\right) \\right) (18) C_k = \\sum_{h \\in H} GP_h \\cdot GE_{k,h} + \\sum_{h \\in H} MP_h \\cdot ME_{k,h} + \\sum_{i \\in I} d_{k,i} \\left( \\tau_{k,i} - \\left( \\sum_{h \\in H} r_{k,i,h} \\cdot h + t_{k,i} - 1 \\right) \\right) (19)"},{"evidence_id":"v141-b-g02-E16","location":{"location_id":"src-7328a27ed1-p05-c2r2__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.1.12 Demand and supply constraints","anchor_text":"y g p Constraint (15) limits the power that can be drawn from the grid. 6) GEk , h Lkmax , ( k K , h","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"Module 2 computes the microgrid energy price. In this module, microgrid energy ME_{k,h} is a constant and microgrid energy price MP_{h} is a variable."},{"evidence_id":"v141-b-g02-E20","location":{"location_id":"src-7328a27ed1-p05-c2r4__v141-a-M01-pricing","page":5,"printed_page":null,"section":"3.2.1 Objective function","anchor_text":"me The total energy bought from the microgrid is the same as the total energy sold to the microgrid.","equation_id":"Eq. (20)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The total energy bought from the microgrid is the same as the total energy sold to the microgrid. Therefore, microgrid energy price does not have an impact on the total cost. Hence, Eq. (18) does not require the microgrid energy cost. This multi-objective optimization problem is solved by using C_{total} as the sole objective function and the remaining objective functions, C_{k}, are added as inequality constraints (Constraint (24) discussed later). Therefore, the objective function of Module 2 is defined as (20). \\min C_{total} \\quad (20)"}]},{"constraint_id":"v141-c-R006-C004","kind":"mathematical","role":"core","statement":"The price-determination model must keep each household's total cost when trading no greater than its cost without microgrid trading. Scope: ECO-Trade Module 2 price optimization, for each participating household.","expression":"C_{k} \\le C_{k}^{NoTrade}, \\quad (k \\in K) \\quad (24)","formalization_origin":"source","template_id":null,"members":["pricing.local"],"variable_refs":["v141-c-R006-x01"],"parameter_refs":["v141-c-R006-th01","v141-c-R006-th02","v141-c-R006-th03"],"evidence_ids":["v141-b-g02-E20","v141-b-g02-E23"],"ref":"29-smart_home_trading::v141-c-R006::v141-c-R006-C004","source_rule_id":"v141-c-R006","evidence":[{"evidence_id":"v141-b-g02-E20","location":{"location_id":"src-7328a27ed1-p05-c2r4__v141-a-M01-pricing","page":5,"printed_page":null,"section":"3.2.1 Objective function","anchor_text":"me The total energy bought from the microgrid is the same as the total energy sold to the microgrid.","equation_id":"Eq. (20)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The total energy bought from the microgrid is the same as the total energy sold to the microgrid. Therefore, microgrid energy price does not have an impact on the total cost. Hence, Eq. (18) does not require the microgrid energy cost. This multi-objective optimization problem is solved by using C_{total} as the sole objective function and the remaining objective functions, C_{k}, are added as inequality constraints (Constraint (24) discussed later). Therefore, the objective function of Module 2 is defined as (20). \\min C_{total} \\quad (20)"},{"evidence_id":"v141-b-g02-E23","location":{"location_id":"src-7328a27ed1-p06-c1r3__v141-a-M01-participation","page":6,"printed_page":null,"section":"3.3 Module 3: Energy computation module","anchor_text":"fehousehold cost when it participates in microgrid trading must be less ththan or equal to the cost ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"condition"},"source_text":"Constraint (24) implements Pareto optimality. It ensues that a household cost when it participates in microgrid trading must be less than or equal to the cost when it does not participate. C_{k} \\le C_{k}^{NoTrade}, \\quad (k \\in K) \\quad (24)"}]}],"variables":[{"variable_id":"v141-c-R006-x01","symbol":"MP_h","meaning":"Microgrid energy price for timeslot h; decision variable in Module 2 and parameter in Module 3.","kind":"operational","domain":"nonnegative real and bounded above by the grid price: 0 \u003c= MP_h \u003c= GP_h","unit":"cent/kWh","indices":["h"],"evidence_ids":["v141-b-g01-E27","v141-b-g02-E16","v141-b-g02-E22"],"source_rule_id":"v141-c-R006","declaration_ref":"29-smart_home_trading::v141-c-R006::x::v141-c-R006-x01"}],"parameters":[{"parameter_id":"v141-c-R006-th01","symbol":"GP_h","meaning":"Grid energy price for timeslot h; fixed input parameter in the Module 2 price model.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"cent/kWh","indices":["h"],"evidence_ids":["v141-b-g01-E27","v141-b-g02-E22"],"source_rule_id":"v141-c-R006","declaration_ref":"29-smart_home_trading::v141-c-R006::theta::v141-c-R006-th01"},{"parameter_id":"v141-c-R006-th02","symbol":"ME_{k,h}","meaning":"Microgrid energy traded by household k in timeslot h; parameter in Module 2 (variable in Module 3), with positive values representing a buyer and negative values a seller.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kWh","indices":["k","h"],"evidence_ids":["v141-b-g01-E27","v141-b-g02-E16","v141-b-g02-E26"],"source_rule_id":"v141-c-R006","declaration_ref":"29-smart_home_trading::v141-c-R006::theta::v141-c-R006-th02"},{"parameter_id":"v141-c-R006-th03","symbol":"C_k^{NoTrade}","meaning":"Total cost of household k when it does not participate in microgrid energy trading; fixed no-trade baseline in the Module 2 Pareto constraint.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"cent","indices":["k"],"evidence_ids":["v141-b-g01-E12","v141-b-g02-E23"],"source_rule_id":"v141-c-R006","declaration_ref":"29-smart_home_trading::v141-c-R006::theta::v141-c-R006-th03"},{"parameter_id":"v141-c-R006-th04","symbol":"DS_{k,h}","meaning":"Initial energy demand or supply of household k at timeslot h from Module 1; parameter in Module 2 and used to initialize ME_{k,h} for the first Module 2 solve.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kWh","indices":["k","h"],"evidence_ids":["v141-b-g01-E11","v141-b-g01-E27"],"source_rule_id":"v141-c-R006","declaration_ref":"29-smart_home_trading::v141-c-R006::theta::v141-c-R006-th04"}]}],"source_definitions":[{"unit_id":"29-smart_home_trading::v141-a-M01::pricing.local","stage":"L6","subtype":"constrained_optimization_price_formation","projection_status":"clear","target_definition":"Module 2 fixes the transaction quantity ME_{k,h}, obtains the microgrid unit electricity price MP_h in a model with min C_{total} as the objective, and satisfies 0≤MP_h≤GP_h and C_k≤C_k^{NoTrade} for each household; the resulting price remains fixed during the solution of Module 3.","form_kind":"mathematical","identity_fields":["Object: microgrid electricity unit price MP_h","Core operation: optimize price determination under fixed transaction quantity, price bounds, and household cost protection conditions","Output: time-of-use microgrid price used by the quantity allocation model"],"variation_fields":["The price unit is cent/kWh, with the grid price GP_h as the upper bound","In the first round, the transaction quantity is initialized with DS_{k,h} from Module 1, and subsequently ME_{k,h} from Module 3 is used","In each round, the price is determined first, and then the transaction quantity","C_{total} does not directly include MP_h; MP_h enters the constraints through the transaction payment in household costs","The no-transaction cost benchmark is provided by Module 1"],"constraint_refs":["29-smart_home_trading::v141-c-R006::v141-c-R006-C001","29-smart_home_trading::v141-c-R006::v141-c-R006-C002","29-smart_home_trading::v141-c-R006::v141-c-R006-C003","29-smart_home_trading::v141-c-R006::v141-c-R006-C004","29-smart_home_trading::v141-c-R001::v141-c-R001-C001","29-smart_home_trading::v141-c-R001::v141-c-R001-C002"],"paper_id":"29-smart_home_trading","mechanism_id":"v141-a-M01","function":"pricing.local","template_code":"JOC"}],"source_variants":[],"functional":{"is_child":false,"subdivision_pending":false},"canonical_pointer":"/nodes/10"});
